import json
import os
import requests
from .models import RequestType
from .exceptions import RpcError, NotSupportedRequestType

REQUEST_TIMEOUT = 60 * 8


def get_default_cert_bundle():
    certbundlefile = os.path.join(os.path.dirname(__file__), "RootCertsBundle.crt")
    return certbundlefile


class Rpc:
    """
    Dynamic Rpc

    Dynamic method resolution of RPC.

    If you provide transport type directly than it takes precedence over indirect transport selection.
    If transport type is not provided then it is selected indirectly:

    - if certificates bundle is provided then we spek over https
    - if provided port is 443 then we speak over https
    - else we use http

    If port is not provided then we use default port numbers (http: 80, https: 443)

    Whenever client calls method non visible in Rpc class like::
      `rpc.attach(ue_id=id)

    then it is on-the-fly converted to `rpc.call(method="attach", ue_id=id)`
    and then passed over to remote side as JSON-RPC 2.0
    So, `rpc.attach()` assumes existence of same named method exposed by Rpc server.
    """

    def __init__(self, hostname, port=None, transport_type=None, certbundle=None):
        """
        Establish JSON-RPC connection over http or https transport.

        If you provide transport type directly than it takes precedence over indirect transport selection.
        If transport type is not provided then it is selected indirectly:
        - if certificates bundle is provided then we spek over https
        - if provided port is 443 then we speak over https
        - else we use http

        If port is not provided then we use default port numbers (http: 80, https: 443)

        When https is selected (anyway) but no certificate is given
        then we use development time certificates (self-signed) - double check if that matches with UE-proxy server.
        (UE-proxy server uses dev-time certs when started with --dev_https flag)
        """
        if transport_type is None:
            if certbundle or (port == 443):
                transport_type = "https"
            else:
                transport_type = "http"
        assert transport_type in ["http", "https"]

        if port is None:
            port = 80 if transport_type == "http" else 443

        self.hostname = hostname
        self.port = port
        self.transport_type = transport_type
        self.remote_url = f"{transport_type}://{hostname}:{port}"
        self.remote_rpc_endpoint = "/api/v1/jsonrpc"
        if certbundle:
            if not os.path.isfile(certbundle):
                raise TypeError(f"certbundle={certbundle} is not file or doesn't exist")
        else:
            certbundle = get_default_cert_bundle()
        self.certbundle = certbundle
        self._req_id = 0

    @staticmethod
    def _send_post_request(url, certbundle, timeout=REQUEST_TIMEOUT, data=None):
        response = requests.post(url, data=json.dumps(data), verify=certbundle, timeout=timeout)
        response.raise_for_status()  # Raises HTTPError, if one occurred
        return response.json()

    @staticmethod
    def _validate_response(request, response, remote):
        if 'result' not in response:
            err = response['error'] if 'error' in response else response
            raise RpcError(request=request, response=err, remote=remote)
        return response['result']

    def _next_msg_id(self):
        self._req_id = (self._req_id + 1) % 60000
        return self._req_id

    def notify(self, method, **kwargs):
        """
        Notify with POST request.

        No response expected for notification.
        In "id" field there is no value - see: https://www.jsonrpc.org/specification#notification

        :param method: method name
        :param kwargs: method parameters
        :return: None
        """
        rpc_payload = {"jsonrpc": "2.0",
                       # no "id" field - see: https://www.jsonrpc.org/specification#notification
                       "method": method,
                       "params": kwargs}
        self._send_post_request(url=f"{self.remote_url}{self.remote_rpc_endpoint}",
                                certbundle=self.certbundle,
                                data=rpc_payload)
        return None  # no response expected from notification

    def _prepare_and_send_post_request(self, method, params, timeout):
        rpc_payload = {"jsonrpc": "2.0",
                       "id": self._next_msg_id(),  # method and self taken from stack
                       "method": method,
                       "params": params}
        response = self._send_post_request(url=f"{self.remote_url}{self.remote_rpc_endpoint}",
                                           certbundle=self.certbundle,
                                           data=rpc_payload,
                                           timeout=timeout)
        method_call = "{}({})".format(method, ", ".join([f"{par}={val}" for par, val in params.items()]))
        result = self._validate_response(request=method_call, response=response,
                                         remote=f"{self.remote_url}{self.remote_rpc_endpoint}")
        return result

    def _send_get_request(self, method, params, timeout=REQUEST_TIMEOUT):
        response = requests.get(url=f"{self.remote_url}{self.remote_rpc_endpoint}/{method}",
                                params=params,
                                verify=self.certbundle,
                                timeout=timeout)
        response.raise_for_status()
        return response

    def __getattr__(self, item):
        """
        Dynamic method resolution of RPC.

        Whenever client calls method non visible in Rpc class
        like:  rpc.attach(ue_id=id)
        then it is on-the-fly converted to
        rpc.call(method="attach", ue_id=id)
        and then passed over to remote side as JSON-RPC 2.0
        So, rpc.attach() assumes existence of same named method exposed by Rpc server.
        """
        method = item

        def _call_remote_method(*args, **kwargs):
            if args:
                what = "only keyword arguments allowed"
                args_str = ", ".join(args)
                err_msg = f"Incorrect RPC call '{method}({args_str})' - {what}"
                raise TypeError(err_msg)
            request_type = kwargs.pop("request_type", "post")
            request_timeout = kwargs.pop("request_timeout", REQUEST_TIMEOUT)
            params = kwargs if kwargs else {}
            if request_type == RequestType.post:
                return self._prepare_and_send_post_request(method, params, request_timeout)
            elif request_type == RequestType.get:
                return self._send_get_request(method, params, request_timeout)
            else:
                raise NotSupportedRequestType(request_type)

        return _call_remote_method
